import {mockupsForPfOrder,appendMockupOverview} from './admin-mockups.mjs';
import {nextStep,isTestOrder,dateTime,paymentLabel} from './admin-order-state.mjs';
export function workQueue(orders,checkouts){return orders.filter(o=>!isTestOrder(o,checkouts.find(c=>c.id===o.checkoutId))).map(order=>{const checkout=checkouts.find(c=>c.id===order.checkoutId),[owner,next]=nextStep(order),blockers=[];
 if(['needs_attention','needs_reconciliation'].includes(order.status))blockers.push(order.pfStatusInformation||'Afklar PF-status og hændelseslog.');
 if(checkout&&['authorization_expired','capture_reconciliation','payment_failed'].includes(checkout.status))blockers.push(paymentLabel(checkout));
 if(order.lines?.some(l=>l.decorations?.length)&&!mockupsForPfOrder(checkout,order).length)blockers.push('Kontrollér designvisning og mockups på ordren.');
 if(['shipped','partially_shipped'].includes(order.status)&&!order.shipment?.trackingDetails?.some(t=>t.trackingURL))blockers.push('Trackinglink mangler.');
 return {order,checkout,owner,next,blockers,bucket:['shipped','partially_shipped'].includes(order.status)?'deliveries':['approval_recorded','processing','confirmed'].includes(order.status)?'production':['awaiting_proof','proof_received','revision_requested','approval_pending_pf'].includes(order.status)?'proofs':'orders'};});}
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export function renderWorkQueue(container,orders,checkouts,view='overview',mailRows=[]){const rows=workQueue(orders,checkouts),active=rows.filter(r=>r.order.status!=='cancelled'),metrics=el('div');metrics.className='metrics';for(const [key,label,items] of [['actions','Kræver handling',active.filter(r=>r.owner==='Smerch'||r.blockers.length)],['proofs','Korrektur',active.filter(r=>r.bucket==='proofs')],['production','Produktion',active.filter(r=>r.bucket==='production')],['deliveries','Leveringer',active.filter(r=>r.bucket==='deliveries')]]){const a=el('a');a.href='/admin#'+key;a.className='metric';a.append(el('strong',String(items.length)),el('span',label));metrics.append(a);}container.append(metrics);if(['overview','actions','blocked','deliveries'].includes(view))for(const mail of mailRows.filter(m=>m.status!=='sent')){const card=el('article');card.className='panel';const a=el('a','Åbn forsendelse →');a.href='/admin/pf-orders#order='+mail.orderId;card.append(el('strong',mail.status==='review'?'Forsendelsesmail klar til gennemgang':'Forsendelsesmail kræver handling'),el('p',(mail.problems||[]).join(' ')||mail.error||mail.to),a);container.append(card);}
 const filtered=active.filter(r=>view==='overview'||view==='actions'?r.owner==='Smerch'||r.blockers.length:view==='blocked'?r.blockers.length:r.bucket===view);
 for(const r of filtered){const card=el('article');card.className='order-summary-card';const gallery=el('div'),info=el('div'),state=el('div');appendMockupOverview(gallery,mockupsForPfOrder(r.checkout,r.order),{decorated:r.order.lines?.some(l=>l.decorations?.length)});info.append(el('h3',(r.order.pfOrderNumber?'Ordre '+r.order.pfOrderNumber:r.order.purchaseOrderNumber)||r.order.id),el('p',r.order.shipping?.company||r.order.shipping?.name||'Kunde mangler'),el('small',dateTime(r.order.createdAt)));for(const l of r.order.lines||[])info.append(el('p',`${l.quantity} × ${r.checkout?.productNames?.[l.productId]||l.productName||l.sku}`));state.append(el('strong','Næste: '+r.owner),el('p',r.next));for(const issue of r.blockers)state.append(el('p',issue));const open=el('a','Åbn ordre →');open.className='action';open.href='/admin/pf-orders#order='+encodeURIComponent(r.order.id);state.append(open);card.append(gallery,info,state);container.append(card);}if(!filtered.length)container.append(el('p','Ingen ordrer kræver handling i denne visning.'));
 for(const c of checkouts.filter(c=>!c.adminTest&&!orders.some(o=>o.checkoutId===c.id)&&['authorized','capture_reconciliation'].includes(c.status))){const p=el('p'),a=el('a','Åbn ordre og betalingsdetaljer');a.href='/admin#orders';p.append(document.createTextNode('Ordre uden PF-tilknytning: '+(c.shipping?.name||c.id)+' · '+(c.pfHandoff?.reason||paymentLabel(c))+' '),a);container.append(p);}
}
